"Our 30,000 m² manufacturing base, a 50-engineer R&D team and more than 500 staff build up to 2 million UPS units and 500,000 solar inverters every year. Quality is controlled at every production stage, and our management systems are certified to ISO 9001, ISO 14001 and ISO 45001.": "تنتج قاعدة التصنيع لدينا بمساحة 30,000 م² وفريق بحث وتطوير من 50 مهندسًا وأكثر من 500 موظف ما يصل إلى مليوني جهاز UPS و500,000 عاكس شمسي سنويًا. تخضع الجودة للرقابة في كل مرحلة إنتاج، وأنظمة الإدارة لدينا حاصلة على شهادات ISO 9001 وISO 14001 وISO 45001.",
"With more than 20 years in the industry we export to North and South America, Europe, the Middle East and Africa — and design custom models and OEM brands for importers in each market.": "بخبرة تتجاوز 20 عامًا في هذه الصناعة، نصدّر إلى أمريكا الشمالية والجنوبية وأوروبا والشرق الأوسط وأفريقيا — ونصمّم طرازات مخصصة وعلامات OEM للمستوردين في كل سوق.",
