"True double-conversion rack-mount UPS for server racks and network cabinets: 0 ms transfer, pure sine wave, standard and long-run models. Factory direct from China.": "UPS أونلاين حقيقي بتحويل مزدوج للتركيب في الرف لخزائن الخوادم والشبكات: تحويل 0 ميلي ثانية، موجة جيبية نقية، طرازات قياسية وطويلة الاحتياط. مباشرة من المصنع في الصين.",
"Zero-break power for ": "طاقة دون أي انقطاع لـ",
"servers & network racks": "الخوادم وخزائن الشبكات",
"True online double-conversion: your equipment always runs on clean power made by the inverter, so a blackout or voltage swing never reaches it. 19-inch rack format, internal batteries or external battery banks for hours of runtime.": "أونلاين حقيقي بتحويل مزدوج: تعمل معداتك دائمًا على طاقة نظيفة يولّدها العاكس، فلا يصل إليها انقطاع التيار أو تقلّب الجهد أبدًا. بمقاس رف 19 بوصة، مع بطاريات داخلية أو بنوك بطاريات خارجية لساعات من التشغيل.",
