"Estimates for new lead-acid batteries at 25 °C. Standard models have internal batteries for short outages; long-run models connect to an external battery bank sized for your runtime. Lithium-ion models are calculated with 85% usable energy.": "تقديرات لبطاريات رصاص حمضية جديدة عند 25 °C. تحتوي الطرازات القياسية على بطاريات داخلية للانقطاعات القصيرة؛ وتتصل الطرازات طويلة الاحتياط ببنك بطاريات خارجي يُحدَّد حجمه حسب زمن التشغيل. تُحسب طرازات الليثيوم أيون بطاقة قابلة للاستخدام 85%.",
