"Online double-conversion, step by step": "التحويل المزدوج أونلاين، خطوة بخطوة",
"Mains power is first turned into DC, then rebuilt into a perfect sine wave by the inverter. The battery sits on the DC bus, so when power fails there is nothing to switch.": "تتحوّل كهرباء الشبكة أولًا إلى تيار مستمر، ثم يعيد العاكس بناءها موجةً جيبية مثالية. البطارية متصلة بناقل التيار المستمر، فلا يوجد ما يُحوَّل عند انقطاع الكهرباء.",
"Normal": "عادي",
"Power failure": "انقطاع الكهرباء",
"Bypass": "المسار الجانبي (Bypass)",
"Rectifier converts mains to DC and charges the battery; the inverter makes clean, regulated AC for the load.": "يحوّل المقوّم كهرباء الشبكة إلى تيار مستمر ويشحن البطارية؛ ويولّد العاكس تيارًا مترددًا نظيفًا ومنظّمًا للحمل.",
"Mains is gone: the battery feeds the inverter instantly. The load sees no interruption — 0 ms.": "انقطعت الكهرباء: تغذّي البطارية العاكس فورًا. لا يشعر الحمل بأي انقطاع — 0 ميلي ثانية.",
"On overload or an internal fault the static bypass connects the load straight to mains, keeping it powered.": "عند الحمل الزائد أو حدوث عطل داخلي، يوصل المسار الجانبي الثابت الحمل مباشرةً بالشبكة ليبقى مُغذّى.",
"Mains": "الشبكة",
