"Modular online UPS for data centres, hospitals and industry: hot-swappable power modules, N+X redundancy, grow from one module to a full cabinet. Factory direct from China.": "UPS أونلاين معياري لمراكز البيانات والمستشفيات والصناعة: وحدات قدرة قابلة للاستبدال أثناء التشغيل، تكرار N+X، والتوسّع من وحدة واحدة إلى خزانة كاملة. مباشرة من المصنع في الصين.",
"Modular online UPS": "UPS أونلاين معياري",
"Grow your power ": "وسّع قدرتك ",
"one module at a time": "وحدةً تلو الأخرى",
"Start with the modules you need today and add more as your load grows. N+X redundancy keeps the load protected even if a module fails, and every module can be swapped without shutting down.": "ابدأ بالوحدات التي تحتاجها اليوم وأضف المزيد مع نمو الحمل. يُبقي تكرار N+X الحمل محميًا حتى لو تعطّلت وحدة، ويمكن استبدال كل وحدة دون إيقاف التشغيل.",
