"Module failed — the redundant module takes over. The load keeps running and the faulty module is swapped while the system stays online.": "تعطّلت وحدة — تتولّى الوحدة الاحتياطية العمل. يستمر الحمل في العمل وتُستبدل الوحدة المعطّلة بينما يبقى النظام متصلًا.",
"Module failed — without a spare module the load moves to bypass (mains). Choose N+1 to avoid this.": "تعطّلت وحدة — دون وحدة احتياطية ينتقل الحمل إلى المسار الجانبي (الشبكة). اختر N+1 لتجنّب ذلك.",
"Reset": "إعادة ضبط",
