"Industrial-frequency (transformer-based) online UPS, 1–400 kVA: thyristor rectifier, IGBT inverter, output isolation transformer, 6/12-pulse rectifier and N+1 parallel. Factory direct from China.": "UPS أونلاين صناعي منخفض التردد (قائم على محوّل)، 1–400 kVA: مقوّم ثايرستور، عاكس IGBT، محوّل عزل على الخرج، مقوّم 6/12 نبضة وتوازٍ N+1. مباشرة من المصنع في الصين.",
