"the factory floor": "أرض المصنع",
"Transformer-based online UPS with a thyristor rectifier, IGBT inverter and a built-in output isolation transformer — made for motors, drives, generators and unstable grids. Single units or parallel systems.": "UPS أونلاين قائم على محوّل مع مقوّم ثايرستور وعاكس IGBT ومحوّل عزل مدمج على الخرج — مصمّم للمحركات والمشغّلات والمولدات والشبكات غير المستقرة. وحدات مفردة أو أنظمة متوازية.",
