"Built-in": "مدمج",
"Industrial UPS range": "مجموعة UPS الصناعي",
"Why industrial-frequency": "لماذا منخفض التردد (صناعي)",
"Built for loads that hit hard": "مصمّم للأحمال الشديدة",
"Galvanic isolation between battery, DC bus and load. Absorbs inrush and surge currents, keeps neutral-to-earth voltage low and stops faults travelling to sensitive equipment.": "عزل غلفاني بين البطارية وناقل التيار المستمر والحمل. يمتص تيارات الاندفاع والطفرات، ويُبقي جهد التعادل-الأرضي منخفضًا، ويمنع انتقال الأعطال إلى المعدات الحساسة.",
"A proven SCR rectifier rides through voltage swings, spikes and generator supplies; the IGBT inverter gives a clean, regulated sine wave with 0 ms transfer.": "مقوّم SCR مُجرَّب يتحمّل تقلّبات الجهد والارتفاعات المفاجئة وتغذية المولدات؛ ويوفّر عاكس IGBT موجة جيبية نظيفة ومنظّمة بتحويل 0 ميلي ثانية.",
"6- or 12-pulse, with harmonic filter": "6 أو 12 نبضة، مع مرشّح توافقيات",
"Choose the rectifier your grid or generator needs: add an input filter or go 12-pulse to cut input current harmonics and size the generator smaller.": "اختر المقوّم الذي تحتاجه شبكتك أو مولّدك: أضف مرشّح دخل أو اختر 12 نبضة لخفض توافقيات تيار الدخل وتصغير حجم المولد.",
"Parallel for capacity and N+1": "التوازي للسعة وN+1",
"Run several units in parallel to share the load, or add one spare unit (N+1) so a failure never drops the load.": "شغّل عدة وحدات على التوازي لتقاسم الحمل، أو أضف وحدة احتياطية واحدة (N+1) حتى لا يسقط الحمل عند حدوث عطل.",
