"We reply with the UPS, rectifier, parallel layout and battery bank for your site — usually the same day.": "نرد بجهاز UPS والمقوّم وترتيب التوازي وبنك البطاريات المناسب لموقعك — عادةً في اليوم نفسه.",
"Hello, I need an industrial UPS proposal:\n• Supply (phases / voltage): \n• Load (kW): \n• Largest motor (kW, starting method): \n• Runtime: \n• Redundancy: ": "مرحبًا، أحتاج إلى مقترح UPS صناعي:\n• التغذية (الأطوار / الجهد): \n• الحمل (kW): \n• أكبر محرك (kW، طريقة البدء): \n• زمن التشغيل: \n• التكرار: ",
"Send us the supply, load, motors and runtime — we reply on WhatsApp the same day.": "أرسل لنا التغذية والحمل والمحركات وزمن التشغيل — نرد عبر واتساب في اليوم نفسه.",
"Choose the voltage on site.": "اختر الجهد في الموقع.",
"Load kW, largest motor, runtime, N+1, 12-pulse…": "الحمل بالكيلوواط، أكبر محرك، زمن التشغيل، N+1، 12 نبضة…",
"Size this UPS for your load and motors": "حدّد حجم UPS هذا لحملك ومحركاتك",
"Configure an industrial UPS for your site": "كوّن UPS صناعيًا لموقعك",
"Tell us the supply, the load and the biggest motor it has to start. We size the UPS, choose the rectifier and parallel layout and size the batteries — and you watch it build inside the cabinet.": "أخبرنا بالتغذية والحمل وأكبر محرك يجب تشغيله. نحدّد حجم UPS، ونختار المقوّم وترتيب التوازي، ونحدّد حجم البطاريات — وتشاهد بناءه داخل الخزانة.",
