"Fans, pumps, conveyors": "مراوح، مضخات، سيور ناقلة",
"Largest motor started on the UPS": "أكبر محرك يُشغَّل على UPS",
"0 = no motor": "0 = لا يوجد محرك",
"Direct on line": "بدء مباشر على الخط",
"Star-delta": "نجمة-دلتا",
"Soft starter": "بادئ ناعم",
"Variable-speed drive": "مشغّل متغير السرعة",
"A motor started direct-on-line draws about 6× its rated current for a few seconds; star-delta about 2.5×, a soft starter about 3×, a variable-speed drive barely more than its rating. The inverter must carry that peak — on mains failure there is no bypass to help.": "يسحب المحرك الذي يبدأ مباشرة على الخط نحو 6 أضعاف تياره المقنن لبضع ثوانٍ؛ ونجمة-دلتا نحو 2.5 ضعف، والبادئ الناعم نحو 3 أضعاف، والمشغّل متغير السرعة بالكاد أكثر من قيمته المقننة. يجب أن يتحمّل العاكس هذه الذروة — فعند انقطاع الشبكة لا يوجد مسار جانبي للمساعدة.",
"Rectifier": "المقوّم",
"Input harmonics": "توافقيات الدخل",
"6-pulse + filter": "6 نبضات + مرشّح",
"THDi < 10%": "THDi < 10%",
"THDi ≈ 10%": "THDi ≈ 10%",
"12-pulse + filter": "12 نبضة + مرشّح",
"THDi < 5%": "THDi < 5%",
"Single-phase input: thyristor rectifier, no pulse options.": "دخل أحادي الطور: مقوّم ثايرستور، دون خيارات النبضات.",
"12-pulse is available from {k} kVA with three-phase input.": "تتوفر 12 نبضة ابتداءً من {k} kVA مع دخل ثلاثي الطور.",
"A 6-pulse thyristor rectifier draws about 30% current harmonics. A passive filter or a 12-pulse rectifier (phase-shifting transformer + two bridges) cuts them sharply — the generator can then be much smaller and the grid stays clean.": "يسحب مقوّم الثايرستور ذو 6 نبضات نحو 30% توافقيات في التيار. يخفضها المرشّح السلبي أو المقوّم ذو 12 نبضة (محوّل إزاحة الطور + جسران) بشكل كبير — فيمكن عندها أن يكون المولد أصغر بكثير وتبقى الشبكة نظيفة.",
"Capacity only": "السعة فقط",
"One spare unit": "وحدة احتياطية واحدة",
"N: units share the load; if one fails the rest must carry it or the load goes to bypass. N+1: one extra unit, so any single unit can fail or be serviced while the load stays on the inverter.": "N: تتقاسم الوحدات الحمل؛ وإذا تعطّلت إحداها يجب أن تتحمّله البقية وإلا انتقل الحمل إلى المسار الجانبي. N+1: وحدة إضافية واحدة، بحيث يمكن لأي وحدة أن تتعطّل أو تخضع للصيانة بينما يبقى الحمل على العاكس.",
"Click to add": "انقر للإضافة",
