"Hybrid, on-grid and off-grid solar inverters for homes and businesses: lithium battery ready, backup for power cuts, parallel expansion and WiFi app monitoring. Design your solar system online. Factory direct from China.": "عاكسات شمسية هجينة ومتصلة بالشبكة ومنفصلة عنها للمنازل والشركات: جاهزة لبطاريات الليثيوم، طاقة احتياطية عند انقطاع الكهرباء، توسعة متوازية ومراقبة عبر تطبيق WiFi. صمّم نظامك الشمسي عبر الإنترنت. مباشرة من المصنع في الصين.",
"Hybrid · on-grid · off-grid": "هجين · متصل بالشبكة · منفصل عنها",
"Solar power that ": "طاقة شمسية ",
"keeps the lights on": "تُبقي الأنوار مضاءة",
"Inverters that run your home or business on solar by day, on batteries through power cuts and at night, and on the grid only when they must. Lithium battery ready, parallel for more power, monitored from your phone.": "عاكسات تشغّل منزلك أو عملك بالطاقة الشمسية نهارًا، وبالبطاريات أثناء انقطاع الكهرباء وليلًا، وبالشبكة فقط عند الضرورة. جاهزة لبطاريات الليثيوم، قابلة للتوصيل على التوازي لمزيد من القدرة، وتُراقَب من هاتفك.",
