"Solar inverter range": "مجموعة العاكسات الشمسية",
"PV input": "دخل الألواح الشمسية",
"Why our inverters": "لماذا عاكساتنا",
"Built for real-world power problems": "مصمّمة لمشكلات الطاقة في الواقع",
"Backup through power cuts": "طاقة احتياطية أثناء انقطاع الكهرباء",
"When the grid fails the inverter switches to battery and solar in milliseconds — lights, fridge, internet and pumps keep running. Full off-grid models for sites with no grid at all.": "عندما تنقطع الشبكة ينتقل العاكس إلى البطارية والطاقة الشمسية خلال أجزاء من الثانية — تستمر الإنارة والثلاجة والإنترنت والمضخات في العمل. وطرازات منفصلة تمامًا عن الشبكة للمواقع التي لا توجد بها شبكة على الإطلاق.",
"Works with LiFePO4 batteries and talks to the battery BMS over CAN / RS485 for accurate state of charge, safe charging and long battery life. Lead-acid also supported.": "يعمل مع بطاريات LiFePO4 ويتواصل مع نظام إدارة البطارية BMS عبر CAN / RS485 لقياس دقيق لحالة الشحن وشحن آمن وعمر بطارية طويل. ويدعم أيضًا الرصاص الحمضي.",
"Parallel for more power": "التوازي لمزيد من القدرة",
"Connect several inverters in parallel to grow capacity, or build split-phase and three-phase systems from single-phase units.": "وصّل عدة عاكسات على التوازي لزيادة السعة، أو ابنِ أنظمة طور منقسم وثلاثية الطور من وحدات أحادية الطور.",
"WiFi app monitoring": "المراقبة عبر تطبيق WiFi",
"See solar production, home consumption and battery state on your phone, and get alerts — from anywhere.": "شاهد إنتاج الطاقة الشمسية واستهلاك المنزل وحالة البطارية على هاتفك، واحصل على التنبيهات — من أي مكان.",
