"We reply with the inverter, battery and panels for your site — usually the same day.": "نرد بالعاكس والبطارية والألواح المناسبة لموقعك — عادةً في اليوم نفسه.",
"Hello, I need a solar inverter quote:\n• What to power: \n• Power cuts per day: \n• Grid voltage: \n• Battery: \n• Quantity: ": "مرحبًا، أحتاج إلى عرض سعر لعاكس شمسي:\n• ما أريد تشغيله: \n• انقطاعات الكهرباء يوميًا: \n• جهد الشبكة: \n• البطارية: \n• الكمية: ",
"Send us your load, power cuts and grid voltage — we reply on WhatsApp the same day.": "أرسل لنا حملك وانقطاعات الكهرباء وجهد الشبكة — نرد عبر واتساب في اليوم نفسه.",
"Choose the grid voltage on site.": "اختر جهد الشبكة في الموقع.",
"Battery type and kWh, number of panels, parallel units…": "نوع البطارية وسعتها بالكيلوواط ساعة، عدد الألواح، الوحدات المتوازية…",
"Price on request · distributor pricing available": "السعر عند الطلب · أسعار خاصة للموزّعين",
