"Design your solar + battery system": "صمّم نظام الطاقة الشمسية مع البطارية",
"Pick what you want the system to do and the appliances you use. We size the inverter, the battery and the solar panels — and show how the energy flows by day, at night and during a power cut.": "اختر ما تريد أن يقوم به النظام والأجهزة التي تستخدمها. نحدّد حجم العاكس والبطارية والألواح الشمسية — ونوضّح كيف تتدفق الطاقة نهارًا وليلًا وأثناء انقطاع الكهرباء.",
