"Add appliances to size the system.": "أضف أجهزة لتحديد حجم النظام.",
"Above 12 kW single-phase we usually build a three-phase or parallel system.": "فوق 12 kW أحادي الطور نبني عادةً نظامًا ثلاثي الطور أو متوازيًا.",
"Motor start-up (fridge, AC, pump) sets the inverter size — start big motors one at a time.": "بدء تشغيل المحركات (الثلاجة، المكيّف، المضخة) هو ما يحدّد حجم العاكس — شغّل المحركات الكبيرة واحدًا تلو الآخر.",
"Many panels for this load: the inverter is sized up so it can take all the solar power.": "ألواح كثيرة لهذا الحمل: تم تكبير العاكس ليستوعب كامل الطاقة الشمسية.",
"Set the hours of power cuts to size the battery.": "حدّد ساعات انقطاع الكهرباء لتحديد حجم البطارية.",
"Show": "عرض",
"Daytime": "النهار",
"Night": "الليل",
"Solar powers the home first, charges the battery with the surplus — and the rest can go to the grid.": "تغذّي الطاقة الشمسية المنزل أولًا، وتشحن البطارية بالفائض — ويمكن إرسال الباقي إلى الشبكة.",
"No sun: the battery powers the home; the grid is only used when the battery is low.": "لا شمس: تغذّي البطارية المنزل؛ ولا تُستخدم الشبكة إلا عند انخفاض البطارية.",
"Grid down: the inverter disconnects from the grid in milliseconds and keeps the home running on battery and solar.": "انقطعت الشبكة: ينفصل العاكس عن الشبكة خلال أجزاء من الثانية ويُبقي المنزل يعمل على البطارية والطاقة الشمسية.",
