"Choose how you want to send it. The system below is filled in for you.": "اختر طريقة الإرسال. النظام أدناه معبّأ لك.",
"Solar system": "نظام شمسي",
"Hello, I am interested in this solar system:\n• Goal: {goal}\n• Site: {reg} · {ph}\n• Appliances: {items}\n• Daily use: {kwh} kWh · peak {peak} W\n• Inverter: {inv}\n• Battery: {batt}\n• Solar panels: {pv}": "مرحبًا، أنا مهتم بهذا النظام الشمسي:\n• الهدف: {goal}\n• الموقع: {reg} · {ph}\n• الأجهزة: {items}\n• الاستخدام اليومي: {kwh} kWh · الذروة {peak} واط\n• العاكس: {inv}\n• البطارية: {batt}\n• الألواح الشمسية: {pv}",
"Inverter ≥ 1.25 × all appliances running together; motor start-up ≤ 2 × inverter rating for a few seconds.": "العاكس ≥ 1.25 × جميع الأجهزة تعمل معًا؛ بدء تشغيل المحركات ≤ 2 × قدرة العاكس لبضع ثوانٍ.",
"Battery: LiFePO4, 90% usable, 93% inverter efficiency, in 48 V 100 Ah (5.12 kWh) modules. Night use ≈ 60% of the day.": "البطارية: LiFePO4، 90% قابلة للاستخدام، كفاءة العاكس 93%، بوحدات 48 فولت 100 Ah (5.12 kWh). الاستخدام الليلي ≈ 60% من النهار.",
"Solar: the panel size you choose (550 W by default), 75% system efficiency, panel power up to 1.3 × inverter rating. Off-grid adds 20%.": "الطاقة الشمسية: مقاس اللوح الذي تختاره (550 واط افتراضيًا)، كفاءة النظام 75%، قدرة الألواح حتى 1.3 × قدرة العاكس. يضيف النظام المنفصل عن الشبكة 20%.",
"Estimates for selection only — we confirm the final system with you.": "تقديرات للاختيار فقط — نؤكد النظام النهائي معك.",
