"48 V / 51.2 V rack-mount LiFePO4 lithium batteries (server rack batteries) for solar energy storage, telecom and UPS: 19-inch modules, parallel expansion, BMS with CAN / RS485. Build your battery bank online. Factory direct from China.": "بطاريات ليثيوم LiFePO4 للتركيب في الرف بجهد 48 / 51.2 فولت (بطاريات رفوف الخوادم) لتخزين الطاقة الشمسية والاتصالات وأجهزة UPS: وحدات 19 بوصة، توسعة متوازية، BMS مع CAN / RS485. صمّم بنك بطارياتك عبر الإنترنت. مباشرة من المصنع في الصين.",
