"that stack up": "تتراكب معًا",
"Standard 19-inch LiFePO4 modules for solar storage, telecom sites and UPS backup. Slide in more modules when you need more energy — the built-in BMS talks to your inverter over CAN or RS485.": "وحدات LiFePO4 قياسية بمقاس 19 بوصة لتخزين الطاقة الشمسية ومواقع الاتصالات والطاقة الاحتياطية لأجهزة UPS. أدخل مزيدًا من الوحدات عندما تحتاج إلى طاقة أكبر — يتواصل نظام BMS المدمج مع عاكسك عبر CAN أو RS485.",
