"Safe, long-life chemistry": "كيمياء آمنة وطويلة العمر",
"Lithium iron phosphate (LiFePO4) is thermally stable and lasts thousands of cycles — far longer than lead-acid, with no maintenance and no gassing.": "ليثيوم فوسفات الحديد (LiFePO4) مستقر حراريًا ويدوم آلاف الدورات — أطول بكثير من الرصاص الحمضي، دون صيانة ودون انبعاث غازات.",
"19-inch, plug and expand": "19 بوصة، وصّل ووسّع",
"Modules fit a standard 19-inch cabinet or stand. Start small and add modules in parallel as the load or the solar array grows.": "تناسب الوحدات خزانة أو حاملًا قياسيًا بمقاس 19 بوصة. ابدأ صغيرًا وأضف وحدات على التوازي مع نمو الحمل أو مصفوفة الألواح الشمسية.",
"Talks to your inverter": "يتواصل مع عاكسك",
"The built-in BMS reports state of charge and limits over CAN or RS485, so the inverter charges and discharges the bank correctly.": "يرسل نظام BMS المدمج حالة الشحن والحدود عبر CAN أو RS485، فيشحن العاكس البنك ويفرّغه بشكل صحيح.",
"Protected and monitored": "محمية ومراقَبة",
"Cell balancing plus over-voltage, under-voltage, over-current, short-circuit and temperature protection, with SOC LEDs on the front panel.": "موازنة الخلايا مع الحماية من الجهد الزائد والجهد المنخفض والتيار الزائد وقصر الدائرة ودرجة الحرارة، مع مؤشرات LED لحالة الشحن على الواجهة الأمامية.",
