"UPS battery banks": "بنوك بطاريات UPS",
"Off-grid sites": "المواقع المنفصلة عن الشبكة",
"Commercial energy storage": "تخزين الطاقة التجاري",
"Questions buyers ask": "أسئلة يطرحها المشترون",
"How many modules can I connect in parallel?": "كم وحدة يمكنني توصيلها على التوازي؟",
"Most rack modules parallel up to 16 units on one 48 V bus (check the model’s specification). Larger banks are split into groups or built as a high-voltage system — tell us the energy you need.": "يمكن توصيل معظم وحدات الرف على التوازي حتى 16 وحدة على ناقل واحد بجهد 48 فولت (راجع مواصفات الطراز). تُقسَّم البنوك الأكبر إلى مجموعات أو تُبنى كنظام عالي الجهد — أخبرنا بالطاقة التي تحتاجها.",
"Will it work with my inverter?": "هل تعمل مع عاكسي؟",
"It works with inverters that support lithium batteries with CAN or RS485 BMS communication. Send us your inverter brand and model and we confirm the protocol before shipping.": "تعمل مع العاكسات التي تدعم بطاريات الليثيوم باتصال BMS عبر CAN أو RS485. أرسل لنا علامة عاكسك وطرازه وسنؤكد البروتوكول قبل الشحن.",
"How long will the battery bank run my load?": "كم من الوقت سيشغّل بنك البطاريات حملي؟",
"Use the builder above: enter your load in kW and the hours you need. As a rule of thumb, one 5.12 kWh module runs a 1 kW load for about 4.5 hours.": "استخدم أداة التصميم أعلاه: أدخل حملك بالكيلوواط وعدد الساعات التي تحتاجها. كقاعدة عامة، تشغّل وحدة واحدة بسعة 5.12 kWh حملًا قدره 1 kW لنحو 4.5 ساعات.",
"Can I replace my lead-acid batteries with LiFePO4?": "هل يمكنني استبدال بطاريات الرصاص الحمضي بـ LiFePO4؟",
"Yes, if your inverter or UPS has a lithium (or user-defined) charging profile. You need about half the nominal capacity of a lead-acid bank for the same usable energy.": "نعم، إذا كان عاكسك أو جهاز UPS يحتوي على ملف شحن لليثيوم (أو قابل للتحديد من المستخدم). تحتاج إلى نحو نصف السعة الاسمية لبنك الرصاص الحمضي للحصول على الطاقة القابلة للاستخدام نفسها.",
"Do I need a special cabinet?": "هل أحتاج إلى خزانة خاصة؟",
"No. The modules fit any standard 19-inch cabinet or open rack; we can also supply a matching battery cabinet with busbars and cables.": "لا. تناسب الوحدات أي خزانة قياسية بمقاس 19 بوصة أو رف مفتوح؛ ويمكننا أيضًا توفير خزانة بطاريات مطابقة مع قضبان التوصيل والكابلات.",
"kWh you need, or load and hours": "الكيلوواط ساعة التي تحتاجها، أو الحمل وعدد الساعات",
"Brand and model for BMS protocol": "العلامة التجارية والطراز لبروتوكول BMS",
"48 V system, or high voltage": "نظام 48 فولت، أو جهد عالٍ",
"Cabinet": "الخزانة",
"Modules only, or with battery cabinet": "الوحدات فقط، أو مع خزانة بطاريات",
"Home, telecom, server room, off-grid": "منزل، اتصالات، غرفة خوادم، منفصل عن الشبكة",
"For distributors: modules per order": "للموزّعين: عدد الوحدات في الطلب",
"Get a battery quote": "احصل على عرض سعر للبطاريات",
"We reply with the modules, cabinet and cables for your system — usually the same day.": "نرد بالوحدات والخزانة والكابلات المناسبة لنظامك — عادةً في اليوم نفسه.",
"Hello, I need a rack-mount LiFePO4 battery quote:\n• Energy (kWh): \n• Inverter model: \n• Quantity: ": "مرحبًا، أحتاج إلى عرض سعر لبطاريات LiFePO4 للتركيب في الرف:\n• الطاقة (kWh): \n• طراز العاكس: \n• الكمية: ",
"Send us the energy you need and your inverter model — we reply on WhatsApp the same day.": "أرسل لنا الطاقة التي تحتاجها وطراز عاكسك — نرد عبر واتساب في اليوم نفسه.",
"Inverter model, number of modules, battery cabinet…": "طراز العاكس، عدد الوحدات، خزانة البطاريات…",
"Build a battery bank with this module": "صمّم بنك بطاريات بهذه الوحدة",
"Battery builder": "مصمّم البطاريات",
"Battery bank builder": "مصمّم بنك البطاريات",
"Stack your battery bank, module by module": "ركّب بنك بطارياتك وحدةً وحدة",
"Tell us how much energy you need — or your load and backup time. We count the modules, check the discharge current and show the bank in a 19-inch cabinet.": "أخبرنا بكمية الطاقة التي تحتاجها — أو حملك وزمن الاحتياط. نحسب عدد الوحدات، ونتحقق من تيار التفريغ، ونعرض البنك في خزانة 19 بوصة.",
"Size by": "التحديد حسب",
"Energy needed": "الطاقة المطلوبة",
"Load & backup time": "الحمل وزمن الاحتياط",
"Backup time": "زمن الاحتياط",
