"Ask us — we will match a module": "اسألنا — سنختار لك وحدة مناسبة",
"Enter the energy or the load to size the bank.": "أدخل الطاقة أو الحمل لتحديد حجم البنك.",
"More than {p} modules: the bank is split into {g} groups (one per inverter) or built as a high-voltage system — ask us.": "أكثر من {p} وحدات: يُقسَّم البنك إلى {g} مجموعات (واحدة لكل عاكس) أو يُبنى كنظام عالي الجهد — اسألنا.",
"The load current sets the module count — more modules share the discharge current.": "تيار الحمل هو ما يحدّد عدد الوحدات — المزيد من الوحدات يتقاسم تيار التفريغ.",
"This module’s discharge current is not listed — we will check it for your load.": "تيار التفريغ لهذه الوحدة غير مدرج — سنتحقق منه لحملك.",
"TO INVERTER": "إلى العاكس",
"Send this battery bank": "أرسل بنك البطاريات هذا",
"Choose how you want to send it. The bank below is filled in for you.": "اختر طريقة الإرسال. البنك أدناه معبّأ لك.",
"Rack battery bank": "بنك بطاريات الرف",
"Hello, I am interested in this rack-mount LiFePO4 battery bank:\n• Need: {need}\n• Modules: {mods}\n• Energy: {kwh} kWh total / {use} kWh usable\n• Bank: {bank}{extra}": "مرحبًا، أنا مهتم ببنك بطاريات LiFePO4 للتركيب في الرف هذا:\n• الاحتياج: {need}\n• الوحدات: {mods}\n• الطاقة: {kwh} kWh إجمالية / {use} kWh قابلة للاستخدام\n• البنك: {bank}{extra}",
"Usable energy 90% of nominal; 95% efficiency from battery to inverter for backup time.": "الطاقة القابلة للاستخدام 90% من الاسمية؛ وكفاءة 95% من البطارية إلى العاكس لحساب زمن الاحتياط.",
"Discharge current = load ÷ (0.9 × nominal voltage), with 20% margin, shared by all modules.": "تيار التفريغ = الحمل ÷ (0.9 × الجهد الاسمي)، مع هامش 20%، موزّعًا على جميع الوحدات.",
"Up to 16 modules in parallel unless the model specifies otherwise; 42U cabinet with 6U kept for wiring and the busbar.": "حتى 16 وحدة على التوازي ما لم يحدد الطراز خلاف ذلك؛ خزانة 42U مع ترك 6U للأسلاك وقضيب التوصيل.",
"Estimates for selection only — we confirm the final bank with your inverter model.": "تقديرات للاختيار فقط — نؤكد البنك النهائي مع طراز عاكسك.",
"Wall-mount lithium batteries": "بطاريات ليثيوم جدارية",
"Wall-mounted LiFePO4 home batteries (powerwall-type) for solar homes and backup: 5–15 kWh per unit, 48 V or high voltage, parallel expansion, BMS with CAN / RS485 for hybrid inverters. Size your home battery online. Factory direct from China.": "بطاريات منزلية LiFePO4 جدارية (من نوع Powerwall) للمنازل العاملة بالطاقة الشمسية وللطاقة الاحتياطية: 5–15 kWh لكل وحدة، 48 فولت أو جهد عالٍ، توسعة متوازية، BMS مع CAN / RS485 للعاكسات الهجينة. حدّد حجم بطارية منزلك عبر الإنترنت. مباشرة من المصنع في الصين.",
"Home battery · wall-mounted": "بطارية منزلية · جدارية",
"Keep your home running ": "أبقِ منزلك يعمل ",
"through every power cut": "خلال كل انقطاع للكهرباء",
"Slim LiFePO4 batteries that hang on the wall next to your solar inverter. Store the sun for the night, ride through load-shedding, and add more units as your home grows.": "بطاريات LiFePO4 نحيفة تُعلَّق على الحائط بجانب عاكسك الشمسي. خزّن الشمس للّيل، وتجاوز فترات تخفيف الأحمال، وأضف المزيد من الوحدات مع نمو منزلك.",
