"Hangs on the wall like an appliance — no cabinet, no floor space, clean installation next to the inverter.": "تُعلَّق على الحائط كأي جهاز منزلي — دون خزانة ودون شغل مساحة من الأرض، مع تركيب نظيف بجانب العاكس.",
"Safe LiFePO4 inside": "LiFePO4 آمن من الداخل",
"Lithium iron phosphate cells are thermally stable and last thousands of cycles, with no maintenance and no fumes in the home.": "خلايا ليثيوم فوسفات الحديد مستقرة حراريًا وتدوم آلاف الدورات، دون صيانة ودون أبخرة داخل المنزل.",
"Works with hybrid inverters": "تعمل مع العاكسات الهجينة",
"The built-in BMS talks to the inverter over CAN or RS485, so charging, discharging and the state of charge are always correct.": "يتواصل نظام BMS المدمج مع العاكس عبر CAN أو RS485، فيكون الشحن والتفريغ وحالة الشحن صحيحة دائمًا.",
"Add units later": "أضف وحدات لاحقًا",
"Start with one battery and connect more in parallel when you add solar panels or appliances.": "ابدأ ببطارية واحدة ووصّل المزيد على التوازي عندما تضيف ألواحًا شمسية أو أجهزة.",
