"Solar homes": "المنازل العاملة بالطاقة الشمسية",
"Off-grid houses & farms": "المنازل والمزارع المنفصلة عن الشبكة",
"Time-of-use savings": "التوفير حسب تعرفة وقت الاستخدام",
"Questions homeowners and installers ask": "أسئلة يطرحها أصحاب المنازل والمُركِّبون",
"How many kWh does my home need?": "كم كيلوواط ساعة يحتاج منزلي؟",
"Use the builder above: enter the energy you want stored, or your home load and the hours of backup. A typical home with lights, fridge, TV, Wi-Fi and fans uses 1–2 kWh during an evening power cut.": "استخدم أداة التصميم أعلاه: أدخل الطاقة التي تريد تخزينها، أو حمل منزلك وساعات الاحتياط. يستهلك المنزل النموذجي بالإنارة والثلاجة والتلفاز والواي فاي والمراوح 1–2 kWh خلال انقطاع للكهرباء في المساء.",
"Which inverters does it work with?": "مع أي عاكسات تعمل؟",
"Hybrid and off-grid inverters that support lithium batteries with CAN or RS485 BMS communication. Send us your inverter brand and model and we confirm the protocol before shipping.": "العاكسات الهجينة والمنفصلة عن الشبكة التي تدعم بطاريات الليثيوم باتصال BMS عبر CAN أو RS485. أرسل لنا علامة عاكسك وطرازه وسنؤكد البروتوكول قبل الشحن.",
"Can I add more batteries later?": "هل يمكنني إضافة المزيد من البطاريات لاحقًا؟",
"Yes. Connect more units of the same model in parallel (see the parallel limit in the specifications). Mixing very old and new units is not recommended — we can advise on your system.": "نعم. وصّل مزيدًا من الوحدات من الطراز نفسه على التوازي (راجع حد التوازي في المواصفات). لا يُنصح بخلط وحدات قديمة جدًا مع وحدات جديدة — يمكننا تقديم المشورة بشأن نظامك.",
"Indoors or outdoors?": "داخلي أم خارجي؟",
"Install indoors or in a sheltered place, out of direct sun and rain, unless the model has an outdoor IP rating. Keep the recommended clearance for ventilation.": "ركّبها في الداخل أو في مكان محمي، بعيدًا عن أشعة الشمس المباشرة والمطر، ما لم يكن للطراز تصنيف IP للاستخدام الخارجي. اترك المسافة الموصى بها للتهوية.",
"How long does it last?": "كم تدوم؟",
"LiFePO4 cells are rated for thousands of cycles — see the cycle life in the specifications. With daily solar cycling that is many years of service.": "خلايا LiFePO4 مصنّفة لآلاف الدورات — راجع عدد دورات الحياة في المواصفات. مع دورة شحن يومية بالطاقة الشمسية، يعني ذلك سنوات عديدة من الخدمة.",
"48 V or high-voltage system": "نظام 48 فولت أو عالي الجهد",
