"Drop-in sizes": "مقاسات بديلة مباشرة",
"Standard 12 V, 24 V and 48 V voltages and familiar capacities from 6 Ah to 200 Ah — replace lead-acid batteries one for one.": "جهود قياسية 12 فولت و24 فولت و48 فولت وسعات مألوفة من 6 Ah إلى 200 Ah — استبدل بطاريات الرصاص الحمضي واحدة بواحدة.",
"More usable energy": "طاقة قابلة للاستخدام أكبر",
"Use 90% of the capacity instead of about 50% for lead-acid, so a smaller lithium battery can often do the same job.": "استخدم 90% من السعة بدلًا من نحو 50% في الرصاص الحمضي، لذا يمكن غالبًا لبطارية ليثيوم أصغر أن تؤدي المهمة نفسها.",
"Less than half the weight": "أقل من نصف الوزن",
"A 12.8 V 100 Ah battery weighs about 12 kg — a comparable lead-acid battery weighs around 30 kg.": "تزن بطارية 12.8 فولت 100 Ah نحو 12 كجم — بينما تزن بطارية رصاص حمضي مماثلة نحو 30 كجم.",
"Series and parallel": "التوالي والتوازي",
