"Questions about replacing lead-acid with LiFePO4": "أسئلة حول استبدال الرصاص الحمضي بـ LiFePO4",
"Can I use my existing lead-acid charger?": "هل يمكنني استخدام شاحن الرصاص الحمضي الحالي؟",
"Many chargers work if their charge voltage suits LiFePO4 (about 14.2–14.6 V for a 12.8 V battery). A charger with a lithium / LiFePO4 mode is best. Avoid desulphation or equalising modes. Send us the charger or UPS model and we check it.": "تعمل كثير من الشواحن إذا كان جهد الشحن فيها مناسبًا لـ LiFePO4 (نحو 14.2–14.6 فولت لبطارية 12.8 فولت). الأفضل شاحن بوضع ليثيوم / LiFePO4. تجنّب أوضاع إزالة الكبريتات أو المعادلة. أرسل لنا طراز الشاحن أو UPS وسنتحقق منه.",
"Will it fit my UPS?": "هل تناسب جهاز UPS لديّ؟",
"The common UPS sizes (12 V 7 Ah, 9 Ah, 12 Ah, 18 Ah…) use the same voltages. Check the dimensions in the table against your battery compartment; tell us the UPS model if you are unsure.": "تستخدم مقاسات UPS الشائعة (12 فولت 7 Ah و9 Ah و12 Ah و18 Ah…) الجهود نفسها. قارن الأبعاد في الجدول بحجرة البطارية لديك؛ وأخبرنا بطراز UPS إن لم تكن متأكدًا.",
"Which size should I choose?": "أي مقاس أختار؟",
"Use the finder above: choose your lead-acid battery and we show the lithium battery with the same Ah, and the smaller one that gives the same usable energy.": "استخدم أداة البحث أعلاه: اختر بطارية الرصاص الحمضي لديك ونعرض لك بطارية الليثيوم بنفس السعة Ah، والأصغر منها التي تعطي الطاقة القابلة للاستخدام نفسها.",
"How many can I connect in series?": "كم بطارية يمكنني توصيلها على التوالي؟",
"For higher voltages, connect batteries of the same model in series and parallel. Tell us your system voltage and we confirm the configuration — or use a 25.6 V or 51.2 V battery directly.": "للجهود الأعلى، وصّل بطاريات من الطراز نفسه على التوالي والتوازي. أخبرنا بجهد نظامك وسنؤكد التكوين — أو استخدم بطارية 25.6 فولت أو 51.2 فولت مباشرة.",
"Can it be charged in the cold?": "هل يمكن شحنها في البرد؟",
"Do not charge LiFePO4 below 0 °C unless the battery has low-temperature charging protection or heating. Discharging works at lower temperatures.": "لا تشحن LiFePO4 تحت 0 °C ما لم تكن البطارية مزوّدة بحماية للشحن في درجات الحرارة المنخفضة أو بتسخين. أما التفريغ فيعمل في درجات حرارة أدنى.",
"Battery size": "مقاس البطارية",
"Voltage and Ah you replace": "الجهد وAh للبطارية التي تستبدلها",
