"Hello, I need a LiFePO4 lead-acid replacement battery quote:\n• Battery size (V / Ah): \n• Quantity: \n• Application: ": "مرحبًا، أحتاج إلى عرض سعر لبطارية LiFePO4 بديلة للرصاص الحمضي:\n• مقاس البطارية (فولت / Ah): \n• الكمية: \n• الاستخدام: ",
"Send us the battery size and quantity — we reply on WhatsApp the same day.": "أرسل لنا مقاس البطارية والكمية — نرد عبر واتساب في اليوم نفسه.",
"Lead-acid size you replace, application, terminal type…": "مقاس الرصاص الحمضي الذي تستبدله، الاستخدام، نوع الأطراف…",
"Compare this battery with lead-acid": "قارن هذه البطارية بالرصاص الحمضي",
