"Which lithium battery replaces yours?": "أي بطارية ليثيوم تحلّ محل بطاريتك؟",
"Replace one battery — or build a battery bank for your system. We match the voltage, compare weight and usable energy, and show how to connect them.": "استبدل بطارية واحدة — أو صمّم بنك بطاريات لنظامك. نطابق الجهد، ونقارن الوزن والطاقة القابلة للاستخدام، ونوضّح طريقة توصيلها.",
