"Size": "المقاس",
"No {v} V battery in this size — ask us.": "لا توجد بطارية {v} فولت بهذا المقاس — اسألنا.",
"Above {ah} Ah — connect batteries in parallel (see \"Build a battery bank\") or ask us.": "أكثر من {ah} Ah — وصّل البطاريات على التوازي (راجع \"تصميم بنك بطاريات\") أو اسألنا.",
