"The load current needs more batteries in parallel here.": "يتطلب تيار الحمل هنا مزيدًا من البطاريات على التوازي.",
"Use batteries of the same model and age in series; balance them before connecting.": "استخدم بطاريات من الطراز والعمر نفسيهما على التوالي؛ ووازنها قبل التوصيل.",
