"Hello, I am interested in this LiFePO4 battery bank:\n• System: {v} V, {need}\n• Batteries: {model} × {n} ({cfg})\n• Energy: {wh} Wh total / {use} Wh usable": "مرحبًا، أنا مهتم ببنك بطاريات LiFePO4 هذا:\n• النظام: {v} فولت، {need}\n• البطاريات: {model} × {n} ({cfg})\n• الطاقة: {wh} Wh إجمالية / {use} Wh قابلة للاستخدام",
"How we compare": "كيف نقارن",
"Usable energy: about 90% of LiFePO4 capacity and about 50% of lead-acid capacity.": "الطاقة القابلة للاستخدام: نحو 90% من سعة LiFePO4 ونحو 50% من سعة الرصاص الحمضي.",
"Lead-acid weight is estimated at about 0.3 kg per Ah for 12 V.": "يُقدَّر وزن الرصاص الحمضي بنحو 0.3 كجم لكل Ah لبطارية 12 فولت.",
"Battery bank: energy ÷ 90% usable, at most 4 in series and 8 in parallel; the load current is shared by the parallel strings.": "بنك البطاريات: الطاقة ÷ 90% قابلة للاستخدام، بحد أقصى 4 على التوالي و8 على التوازي؛ ويُوزَّع تيار الحمل على السلاسل المتوازية.",
"Estimates for selection only — we confirm the final choice with you.": "تقديرات للاختيار فقط — نؤكد الاختيار النهائي معك.",
"Home ESS all-in-one": "نظام تخزين طاقة منزلي متكامل",
"All-in-one home energy storage systems": "أنظمة تخزين الطاقة المنزلية المتكاملة",
"All-in-one home energy storage systems: LiFePO4 battery and hybrid inverter in one unit, 2.5–25 kWh and 3–10 kW, wall-mounted, floor-standing or stacked (high- and low-voltage), solar and mains input, UPS function. Plan your home backup online. Factory direct from China.": "أنظمة تخزين الطاقة المنزلية المتكاملة: بطارية LiFePO4 وعاكس هجين في وحدة واحدة، 2.5–25 kWh و3–10 kW، جدارية أو أرضية أو مكدّسة (عالية ومنخفضة الجهد)، دخل من الطاقة الشمسية والشبكة، ووظيفة UPS. خطّط للطاقة الاحتياطية لمنزلك عبر الإنترنت. مباشرة من المصنع في الصين.",
"Battery + inverter in one": "بطارية + عاكس في وحدة واحدة",
"Solar storage and backup ": "تخزين الطاقة الشمسية والطاقة الاحتياطية ",
"in one box": "في صندوق واحد",
"The lithium battery and the hybrid inverter in a single unit. Connect solar panels and the grid, plug in your home circuits — and keep the lights, fridge and WiFi on when the power goes out.": "البطارية الليثيوم والعاكس الهجين في وحدة واحدة. وصّل الألواح الشمسية والشبكة، ووصّل دوائر منزلك — لتبقى الإنارة والثلاجة والواي فاي تعمل عند انقطاع الكهرباء.",
"Plan my home backup": "خطّط للطاقة الاحتياطية لمنزلي",
"Battery + inverter": "بطارية + عاكس",
"Wall, floor or stacked": "جدارية أو أرضية أو مكدّسة",
"Solar + mains": "طاقة شمسية + شبكة",
"UPS function": "وظيفة UPS",
"All-in-one home ESS range": "مجموعة أنظمة تخزين الطاقة المنزلية المتكاملة",
"Wall-mounted": "جدارية",
"Stacked": "مكدّسة",
