"Low-voltage stacked": "مكدّسة منخفضة الجهد",
"High-voltage": "عالي الجهد",
"Low-voltage": "منخفض الجهد",
"Battery layers": "طبقات البطارية",
"Everything a solar home needs, already connected": "كل ما يحتاجه المنزل الشمسي، موصول مسبقًا",
"Battery and inverter integrated": "بطارية وعاكس مدمجان",
"One unit replaces a separate inverter, battery, cabling and brackets — fewer parts, faster installation, a tidy result.": "وحدة واحدة تحلّ محل عاكس وبطارية وكابلات وحوامل منفصلة — قطع أقل، وتركيب أسرع، ونتيجة مرتّبة.",
"Solar and mains charging": "الشحن من الطاقة الشمسية والشبكة",
"Charges from solar panels and from the grid, with integrated fast charging, so the battery is ready for the next power cut.": "يشحن من الألواح الشمسية ومن الشبكة، مع شحن سريع مدمج، لتكون البطارية جاهزة لانقطاع الكهرباء التالي.",
"When the grid fails, the unit switches your home circuits to the battery automatically.": "عندما تنقطع الشبكة، تحوّل الوحدة دوائر منزلك إلى البطارية تلقائيًا.",
"Slim wall-mounted units save floor space, compact floor-standing units need no drilling, and stacked systems grow layer by layer up to 25 kWh and 10 kW.": "توفّر الوحدات الجدارية النحيفة المساحة الأرضية، ولا تحتاج الوحدات الأرضية المدمجة إلى ثقب، وتتوسّع الأنظمة المكدّسة طبقةً تلو الأخرى حتى 25 kWh و10 kW.",
"All-in-one or separate?": "متكامل أم منفصل؟",
"All-in-one ESS or separate inverter + battery?": "نظام تخزين متكامل أم عاكس + بطارية منفصلان؟",
"All-in-one home ESS": "نظام تخزين طاقة منزلي متكامل",
"One unit, minimal wiring": "وحدة واحدة، أقل قدر من الأسلاك",
"On the wall, on the floor or one stack": "على الحائط، أو على الأرض، أو مكدّسة",
