"Footprint": "المساحة المشغولة",
"Total weight": "إجمالي الوزن",
"PV input up to": "دخل الألواح الشمسية حتى",
"{cool} alternative": "بديل {cool}",
"Enter the power and hours.": "أدخل القدرة والساعات.",
"The power sets the number of cabinets here — each cabinet adds {kw} kW.": "القدرة هي ما يحدّد عدد الخزائن هنا — كل خزانة تضيف {kw} kW.",
"The PV array sets the number of cabinets here — up to 100 kW of PV per cabinet.": "مصفوفة الألواح الشمسية هي ما يحدّد عدد الخزائن هنا — حتى 100 kW من الألواح لكل خزانة.",
"No published cabinet with {opt} yet — ask us for this configuration.": "لا توجد خزانة منشورة مع {opt} بعد — اطلب منا هذا التكوين.",
"More than {p} cabinets — ask us for a containerised system.": "أكثر من {p} خزائن — اطلب منا نظامًا في حاوية.",
"Backup needs the STS option (≤ 20 ms switchover).": "الطاقة الاحتياطية تتطلب خيار STS (تحويل ≤ 20 ميلي ثانية).",
"C&I ESS": "تخزين تجاري وصناعي",
"C&I energy storage cabinet": "خزانة تخزين طاقة تجارية وصناعية",
"Hello, I am interested in this C&I energy storage configuration:\n• Application: {app}\n• Power: {kw} kW for {h} h{pv}\n• Cabinets: {model} × {n} ({cool})\n• Total: {kwT} kW / {kwh} kWh": "مرحبًا، أنا مهتم بتكوين تخزين الطاقة التجاري والصناعي هذا:\n• الاستخدام: {app}\n• القدرة: {kw} kW لمدة {h} ساعة{pv}\n• الخزائن: {model} × {n} ({cool})\n• الإجمالي: {kwT} kW / {kwh} kWh",
"Energy needed = power × hours ÷ (90% usable × 95% efficiency).": "الطاقة المطلوبة = القدرة × الساعات ÷ (90% قابلة للاستخدام × 95% كفاءة).",
"Cabinets = the largest of: power ÷ PCS power, energy ÷ cabinet energy, PV ÷ 100 kW per cabinet; the fewest cabinets win.": "عدد الخزائن = الأكبر من: القدرة ÷ قدرة PCS، والطاقة ÷ طاقة الخزانة، والألواح ÷ 100 kW لكل خزانة؛ ويُختار الحل بأقل عدد من الخزائن.",
"Backup requires STS and solar storage requires PV DC-DC — models without them are left out.": "الطاقة الاحتياطية تتطلب STS وتخزين الطاقة الشمسية يتطلب DC-DC للألواح — وتُستبعد الطرازات التي لا تحتويهما.",
"Estimates for selection only — we confirm the final system with your load profile.": "تقديرات للاختيار فقط — نؤكد النظام النهائي وفق ملف حملك.",
"Custom": "حسب الطلب",
"Custom Mini UPS": "Mini UPS حسب الطلب",
"Your outputs, your battery, your brand. Built by the factory, from a sample to mass production.": "مخارجك، بطاريتك، علامتك التجارية. يصنعه المصنع، من العيّنة إلى الإنتاج الكمي.",
"Full custom design (ODM)": "تصميم مخصص بالكامل (ODM)",
"Your brand on a standard model (OEM)": "علامتك التجارية على طراز قياسي (OEM)",
"We design a new model around your devices: outputs, voltages, currents and battery.": "نصمّم طرازًا جديدًا حول أجهزتك: المخارج والجهود والتيارات والبطارية.",
"Pick one of our models and we make it with your logo and packaging.": "اختر أحد طرازاتنا وسنصنعه بشعارك وتغليفك.",
