"Hello, I need batteries for a UPS:\n• Load: {w} W, backup {min} min, UPS {dc} V\n• Batteries: {cfg} (≈ {rt} min)\n• Quantity of UPS: ": "مرحبًا، أحتاج إلى بطاريات لجهاز UPS:\n• الحمل: {w} واط، زمن احتياط {min} دقيقة، UPS {dc} فولت\n• البطاريات: {cfg} (≈ {rt} دقيقة)\n• عدد أجهزة UPS: ",
"Hello, I need a solar battery bank:\n• {daily} kWh/day × {days} day(s), {v} V\n• Batteries: {cfg}": "مرحبًا، أحتاج إلى بنك بطاريات شمسي:\n• {daily} kWh/يوم × {days} يوم، {v} فولت\n• البطاريات: {cfg}",
