"How we calculate": "كيف نحسب",
"UPS: inverter efficiency 92%, end voltage 1.75 V per cell (10.5 V per battery); runtime from the battery's constant-power discharge table at 25 °C.": "UPS: كفاءة العاكس 92%، جهد نهائي 1.75 فولت لكل خلية (10.5 فولت لكل بطارية)؛ وزمن التشغيل من جدول التفريغ بالقدرة الثابتة للبطارية عند 25 °C.",
