"One string · {n} × 12 V": "سلسلة واحدة · {n} × 12 فولت",
"kg": "كجم",
"mm": "مم",
"Micro data centre (IDM)": "مركز بيانات مصغّر (IDM)",
"Micro-module data centres": "مراكز بيانات معيارية مصغّرة",
"SKE IDM Ⅱ micro-module data centres: all-in-one single cabinet (≤10 kW), single-row module (2–10 cabinets, 10–60 kW) and dual-row contained-aisle module (up to 48 cabinets, UPS 20–600 kVA). Free configurator: racks + kW → cooling, UPS, batteries and layout.": "مراكز بيانات معيارية مصغّرة SKE IDM Ⅱ: خزانة واحدة متكاملة (≤10 kW)، ووحدة أحادية الصف (2–10 خزائن، 10–60 kW)، ووحدة مزدوجة الصف بممر محتوى (حتى 48 خزانة، UPS 20–600 kVA). مُكوِّن مجاني: الرفوف + الكيلوواط ← التبريد وUPS والبطاريات والمخطط.",
"IDM Ⅱ micro-module": "وحدة معيارية IDM Ⅱ",
"A data centre ": "مركز بيانات ",
"built in the factory": "مبني في المصنع",
"Cabinets, UPS, precision cooling, power distribution, cabling and monitoring delivered as one product. Choose a single all-in-one cabinet, a single row, or a dual-row module with a contained aisle — then grow module by module.": "الخزائن وUPS والتبريد الدقيق وتوزيع الطاقة والكابلات والمراقبة تُسلَّم كمنتج واحد. اختر خزانة واحدة متكاملة، أو صفًا واحدًا، أو وحدة مزدوجة الصف بممر محتوى — ثم توسّع وحدةً تلو الأخرى.",
"Configure my micro data centre": "كوّن مركز البيانات المصغّر الخاص بي",
"See the 3 formats": "عرض الأشكال الثلاثة",
"IT cabinets per module": "خزائن تقنية المعلومات لكل وحدة",
