"All-in-one cabinet": "خزانة متكاملة",
"No equipment room needed. UPS, rack-mount AC, distribution and monitoring inside one 42U cabinet.": "لا حاجة إلى غرفة معدات. UPS ومكيّف للرف والتوزيع والمراقبة داخل خزانة واحدة 42U.",
