"A row of glass-door cabinets with in-row cooling and contained hot/cold aisle for small data rooms.": "صف من الخزائن ذات الأبواب الزجاجية مع تبريد بين الصفوف وممر ساخن/بارد محتوى لغرف البيانات الصغيرة.",
