"IDM2 dual row": "IDM2 صفّان",
"Up to 48 cabinets": "حتى 48 خزانة",
"Two rows face to face around a sealed cold aisle, with roof panels linked to the fire system.": "صفّان متقابلان حول ممر بارد مغلق، مع ألواح سقف مرتبطة بنظام الحريق.",
"20–600 kVA · L ≤ 15 m": "20–600 kVA · الطول ≤ 15 م",
"Hello, I would like a quote for micro data centre {m}.": "مرحبًا، أرغب في عرض سعر لمركز البيانات المصغّر {m}.",
"From racks to a complete module": "من الرفوف إلى وحدة متكاملة",
"Enter how many IT racks and how much power each one draws. The configurator picks the format, then sizes the precision cooling, the UPS, the batteries and the battery cabinets with the same tools as our product pages — and draws the layout.": "أدخل عدد رفوف تقنية المعلومات والقدرة التي يستهلكها كل منها. يختار المُكوِّن الشكل، ثم يحدّد حجم التبريد الدقيق وUPS والبطاريات وخزائن البطاريات بالأدوات نفسها المستخدمة في صفحات منتجاتنا — ويرسم المخطط.",
"IT racks": "رفوف تقنية المعلومات",
