"in the cabinet": "داخل الخزانة",
"Above 15 kW per rack — we will check airflow and suggest chilled-water in-row units.": "أكثر من 15 kW لكل رف — سنتحقق من تدفق الهواء ونقترح وحدات بين الصفوف بالماء المبرّد.",
"More than 48 racks: split into {n} modules (shown: one module).": "أكثر من 48 رفًا: تُقسَّم إلى {n} وحدات (المعروض: وحدة واحدة).",
"Aisle longer than 15 m — split into two modules or use 300 mm in-row units.": "الممر أطول من 15 م — قسّمه إلى وحدتين أو استخدم وحدات بين الصفوف بعرض 300 مم.",
"Batteries above 120 Ah — use an open battery rack or 2 V cells (quoted separately).": "البطاريات أكبر من 120 Ah — استخدم رف بطاريات مفتوحًا أو خلايا 2 فولت (تُسعَّر بشكل منفصل).",
"Large battery bank — we size 2 V VRLA cells (100–3000 Ah) for this load. <a href=\"/{lang}/batteries/vrla-2v/\">2 V cells →</a>": "بنك بطاريات كبير — نحدّد حجم خلايا VRLA بجهد 2 فولت (100–3000 Ah) لهذا الحمل. <a href=\"/{lang}/batteries/vrla-2v/\">خلايا 2 فولت ←</a>",
"Backup time too long for 12 V batteries with up to 4 strings — send us the details.": "زمن الاحتياط أطول من أن تغطيه بطاريات 12 فولت بحد أقصى 4 سلاسل — أرسل لنا التفاصيل.",
"Quote this configuration": "اطلب عرض سعر لهذا التكوين",
"Hello, I need a micro data centre: {r} racks × {kw} kW, {min} min backup. Suggested: {m}, cooling {c}, UPS {u}.": "مرحبًا، أحتاج إلى مركز بيانات مصغّر: {r} رفوف × {kw} kW، زمن احتياط {min} دقيقة. المقترح: {m}، التبريد {c}، UPS {u}.",
