"Built for fast, reliable rooms": "مصمّمة لغرف سريعة وموثوقة",
"Which format do I need?": "أي شكل أحتاج؟",
"One cabinet with up to about 10 kW of IT load and no equipment room: IDM single cabinet. 2–10 cabinets and 10–60 kW in a small room: IDM single row. Larger rooms, up to 48 cabinets per module: IDM2 dual row. The configurator above picks the format for you.": "خزانة واحدة بحمل تقنية معلومات حتى نحو 10 kW ودون غرفة معدات: IDM خزانة واحدة. من 2 إلى 10 خزائن و10–60 kW في غرفة صغيرة: IDM صف واحد. الغرف الأكبر، حتى 48 خزانة لكل وحدة: IDM2 صفّان. يختار المُكوِّن أعلاه الشكل نيابةً عنك.",
"What is included?": "ماذا يشمل؟",
"Cabinets, precision cooling, UPS and batteries, power distribution and PDUs, aisle containment, cabling trays and the monitoring system — see the configuration tables. Every project is confirmed with a final bill of materials.": "الخزائن والتبريد الدقيق وUPS والبطاريات وتوزيع الطاقة ووحدات PDU واحتواء الممر ومسارات الكابلات ونظام المراقبة — راجع جداول التكوين. ويُؤكَّد كل مشروع بقائمة مواد نهائية.",
"Can I use my own UPS or batteries?": "هل يمكنني استخدام UPS أو بطاريات خاصة بي؟",
"Yes. The module can be built around SKE UPS and batteries or integrate equipment you already have; tell us the models.": "نعم. يمكن بناء الوحدة حول UPS وبطاريات SKE أو دمج معدات لديك بالفعل؛ أخبرنا بالطرازات.",
"How long does delivery and installation take?": "كم يستغرق التسليم والتركيب؟",
"Modules are prefabricated and tested in the factory. The all-in-one cabinet is running about 3 hours after it arrives; row modules are assembled on site in days rather than weeks.": "تُصنَّع الوحدات مسبقًا وتُختبر في المصنع. تبدأ الخزانة المتكاملة العمل بعد نحو 3 ساعات من وصولها؛ وتُجمَّع وحدات الصفوف في الموقع خلال أيام لا أسابيع.",
"What power supply does it need?": "ما مصدر التغذية الذي تحتاجه؟",
"380/400/415 V AC, 50/60 Hz, 3Ph+N+PE for row modules. The single cabinet runs on single-phase supply for the 3–10 kVA UPS.": "380/400/415 فولت متردد، 50/60 هرتز، 3 أطوار + N + PE لوحدات الصفوف. وتعمل الخزانة الواحدة بتغذية أحادية الطور لـ UPS بقدرة 3–10 kVA.",
"Planning a server room or edge site?": "تخطط لغرفة خوادم أو موقع حوسبة طرفية؟",
"Send the number of racks, power per rack, backup time and room size — we reply with the layout, bill of materials and price.": "أرسل عدد الرفوف والقدرة لكل رف وزمن الاحتياط ومساحة الغرفة — نرد بالمخطط وقائمة المواد والسعر.",
"Size cooling, UPS and batteries for your module": "حدّد حجم التبريد وUPS والبطاريات لوحدتك",
"IT cabinets": "خزائن تقنية المعلومات",
"Catalogue (PDF)": "الكتالوج (PDF)",
"Power & environment monitoring": "مراقبة الطاقة والبيئة",
"SKE SK-DEM power & environment monitoring host for server rooms and micro data centres: 8 serial ports, 8 digital inputs, infrared, Wiegand access and dual Ethernet. Monitors UPS, precision AC, distribution, batteries, PDUs, sensors, access and video. Free monitoring-point planner.": "وحدة مراقبة الطاقة والبيئة SKE SK-DEM لغرف الخوادم ومراكز البيانات المصغّرة: 8 منافذ تسلسلية، 8 مداخل رقمية، الأشعة تحت الحمراء، تحكّم بالدخول Wiegand، ومنفذا إيثرنت. تراقب UPS والتكييف الدقيق والتوزيع والبطاريات ووحدات PDU والحسّاسات والدخول والفيديو. مخطِّط مجاني لنقاط المراقبة.",
"SK-DEM monitoring host": "وحدة المراقبة SK-DEM",
"See every UPS, AC and sensor ": "شاهد كل UPS ومكيّف وحسّاس ",
"on one screen": "على شاشة واحدة",
"One 1U host collects data from the UPS, air conditioners, power distribution, batteries and environment sensors of a room or micro-module, raises alarms by screen, app, SMS, voice and e-mail, and uploads to a central DCIM.": "وحدة واحدة بارتفاع 1U تجمع البيانات من UPS والمكيّفات وتوزيع الطاقة والبطاريات وحسّاسات البيئة في غرفة أو وحدة معيارية، وتطلق الإنذارات عبر الشاشة والتطبيق والرسائل النصية والمكالمات الصوتية والبريد الإلكتروني، وترفع البيانات إلى نظام DCIM مركزي.",
"Plan my monitoring points": "خطّط لنقاط المراقبة لديّ",
"See the interfaces": "عرض الواجهات",
"serial ports RS485/RS232": "منافذ تسلسلية RS485/RS232",
"digital inputs": "مداخل رقمية",
"Ethernet ports": "منافذ إيثرنت",
"19\" rack-mount": "للتركيب في رف 19\"",
"What plugs into the SK-DEM": "ما الذي يتصل بـ SK-DEM",
"Monitoring-point planner": "مخطِّط نقاط المراقبة",
"What do you want to monitor?": "ماذا تريد أن تراقب؟",
"Enter how many of each device and sensor the room has. The planner shows which SK-DEM port each one uses, how full the host is, and how many hosts you need. RS485 devices of the same type share one serial port (by address).": "أدخل عدد كل نوع من الأجهزة والحسّاسات في الغرفة. يوضّح المخطِّط أي منفذ في SK-DEM يستخدمه كل منها، ومدى امتلاء الوحدة، وكم وحدة تحتاج. تتشارك أجهزة RS485 من النوع نفسه منفذًا تسلسليًا واحدًا (حسب العنوان).",
