"Cameras connect through an NVR and the network switch (Ethernet), not to the collection ports.": "تتصل الكاميرات عبر NVR ومحوّل الشبكة (إيثرنت)، لا بمنافذ التجميع.",
"Add some devices to see the wiring plan.": "أضف بعض الأجهزة لرؤية مخطط التوصيل.",
