"Hello, I need power & environment monitoring: {list}. Suggested: {n} × SK-DEM.": "مرحبًا، أحتاج إلى مراقبة الطاقة والبيئة: {list}. المقترح: {n} × SK-DEM.",
"Network": "الشبكة",
"Solutions": "الحلول",
"Software": "البرمجيات",
"Which equipment can SK-DEM monitor?": "ما المعدات التي يمكن لـ SK-DEM مراقبتها؟",
"UPS (RS485, RS232 or SNMP), precision and in-row air conditioners, precision distribution cabinets, smart PDUs, battery monitoring, temperature/humidity, smoke, water leak, infrared, access control and video. Tell us the brands and models — we confirm the protocols.": "UPS (RS485 أو RS232 أو SNMP)، والمكيّفات الدقيقة وبين الصفوف، وخزائن التوزيع الدقيقة، ووحدات PDU الذكية، ومراقبة البطاريات، والحرارة/الرطوبة، والدخان، وتسرّب المياه، والأشعة تحت الحمراء، والتحكم في الدخول، والفيديو. أخبرنا بالعلامات التجارية والطرازات — ونؤكد البروتوكولات.",
"Does it need a server or PC?": "هل تحتاج إلى خادم أو كمبيوتر؟",
"No. SK-DEM manages the site locally with its own web interface and an optional 21\" touch screen. A PC, the mobile app and a central DCIM platform are optional.": "لا. تدير SK-DEM الموقع محليًا بواجهة ويب خاصة بها وشاشة لمس 21\" اختيارية. أما الكمبيوتر وتطبيق الهاتف ومنصة DCIM المركزية فهي اختيارية.",
"How are alarms sent?": "كيف تُرسل الإنذارات؟",
"On the touch screen and web page, by audible/visual alarm on site, and by SMS (SIM card), voice call, e-mail and the mobile app.": "على شاشة اللمس وصفحة الويب، وبإنذار صوتي/ضوئي في الموقع، وعبر الرسائل النصية (بطاقة SIM) والمكالمات الصوتية والبريد الإلكتروني وتطبيق الهاتف.",
"Can it report to our existing monitoring platform?": "هل يمكنها إرسال البيانات إلى منصة المراقبة الحالية لدينا؟",
"Yes. Standard third-party (northbound) interfaces upload the data over the network to a central management platform.": "نعم. ترفع الواجهات القياسية للأطراف الثالثة (الاتجاه الشمالي) البيانات عبر الشبكة إلى منصة إدارة مركزية.",
"What about several rooms or sites?": "ماذا عن عدة غرف أو مواقع؟",
"Install one SK-DEM per room; a DCIM server in the monitoring centre manages all rooms — assets, operations, energy and capacity.": "ركّب وحدة SK-DEM واحدة لكل غرفة؛ ويدير خادم DCIM في مركز المراقبة جميع الغرف — الأصول والتشغيل والطاقة والسعة.",
"Need monitoring for a server room?": "تحتاج إلى مراقبة لغرفة خوادم؟",
"Send the equipment list (UPS, AC, distribution, sensors, doors, cameras) — we reply with the points list, wiring plan and price.": "أرسل قائمة المعدات (UPS، التكييف، التوزيع، الحسّاسات، الأبواب، الكاميرات) — نرد بقائمة النقاط ومخطط التوصيل والسعر.",
"Plan the monitoring points for your room": "خطّط لنقاط المراقبة في غرفتك",
"Mounting": "التركيب",
"1U 19\" rack-mount": "للتركيب في رف 19\" بارتفاع 1U",
