"SKE Power manufactures UPS systems from mini DC UPS to 1200 kVA modular UPS, solar inverters, home and C&I energy storage, and LiFePO4 batteries. Size your system online and get a factory quote.": "تصنّع SKE Power أنظمة UPS من Mini DC UPS إلى UPS معياري بقدرة 1200 kVA، وعاكسات شمسية، وأنظمة تخزين طاقة منزلية وتجارية وصناعية، وبطاريات LiFePO4. حدّد حجم نظامك عبر الإنترنت واحصل على عرض سعر من المصنع.",
