"Our Beijing company specializes in power engineering, electrical and electronic equipment, IT product sales, technology development and after-sales service. It delivers integrated power solutions and IT infrastructure projects for users across many sectors.": "تتخصص شركتنا في بكين في هندسة الطاقة، والمعدات الكهربائية والإلكترونية، ومبيعات منتجات تقنية المعلومات، وتطوير التقنيات، وخدمة ما بعد البيع. وتقدّم حلول طاقة متكاملة ومشاريع بنية تحتية لتقنية المعلومات للمستخدمين في قطاعات عديدة.",
