"1U 19\" rack-mount · micro-module and room monitoring": "للتركيب في رف 19\" بارتفاع 1U · مراقبة الوحدات المعيارية والغرف",
"SK-DEM is the SKE power & environment monitoring host. It acquires, processes, alarms and displays data in one unit, bringing the UPS, precision air conditioners, power distribution, batteries and PDUs of a room or micro-module — plus temperature/humidity, smoke, water leak, access control and video — into one system. With a 21\" touch screen, web platform and mobile app it manages the site locally without a host PC, and standard third-party interfaces upload data to a central platform.": "SK-DEM هي وحدة مراقبة الطاقة والبيئة من SKE. تجمع البيانات وتعالجها وتطلق الإنذارات وتعرضها في وحدة واحدة، فتضم UPS والمكيّفات الدقيقة وتوزيع الطاقة والبطاريات ووحدات PDU في غرفة أو وحدة معيارية — إضافةً إلى الحرارة/الرطوبة والدخان وتسرّب المياه والتحكم في الدخول والفيديو — في نظام واحد. ومع شاشة لمس 21\" ومنصة ويب وتطبيق للهاتف، تدير الموقع محليًا دون كمبيوتر مضيف، وترفع الواجهات القياسية للأطراف الثالثة البيانات إلى منصة مركزية.",
"Front-panel interfaces": "واجهات اللوحة الأمامية",
"Digital inputs (dry contacts: smoke, leak, door contacts…)": "مداخل رقمية (تلامسات جافة: دخان، تسرّب، مستشعرات الأبواب…)",
"Analogue inputs": "مداخل تناظرية",
"Infrared detector inputs": "مداخل كواشف الأشعة تحت الحمراء",
"Serial ports (RS485 / RS232 for UPS, AC, distribution, batteries, PDU, T/H sensors)": "منافذ تسلسلية (RS485 / RS232 لـ UPS والتكييف والتوزيع والبطاريات وPDU وحسّاسات الحرارة/الرطوبة)",
"Bus ports": "منافذ الناقل",
