"Ethernet (TCP/IP, SNMP, video, upload to platform)": "إيثرنت (TCP/IP، SNMP، الفيديو، الرفع إلى المنصة)",
"USB ports": "منافذ USB",
"SIM slot (SMS alarms) · SD slot (data storage)": "فتحة SIM (إنذارات الرسائل النصية) · فتحة SD (تخزين البيانات)",
"Port names as printed on the front panel; electrical ratings per the datasheet.": "أسماء المنافذ كما هي مطبوعة على اللوحة الأمامية؛ والقيم الكهربائية حسب ورقة البيانات.",
"What it monitors": "ما الذي تراقبه",
"UPS (RS485 / RS232 / SNMP)": "UPS (RS485 / RS232 / SNMP)",
"Precision / in-row AC (RS485)": "مكيّف دقيق / بين الصفوف (RS485)",
