"Battery banks (voltage, current, internal resistance)": "بنوك البطاريات (الجهد، التيار، المقاومة الداخلية)",
"Temperature/humidity, smoke, water leak, infrared": "الحرارة/الرطوبة، الدخان، تسرّب المياه، الأشعة تحت الحمراء",
"Smart access control, video surveillance": "التحكم الذكي في الدخول، المراقبة بالفيديو",
"Roof panels, lighting, audible/visual alarm (I/O linkage)": "ألواح السقف، الإنارة، الإنذار الصوتي/الضوئي (ربط الإدخال/الإخراج)",
"Alarms and access": "الإنذارات والدخول",
"21\" touch screen / duty PC": "شاشة لمس 21\" / كمبيوتر المناوبة",
"Web platform, mobile app": "منصة ويب، تطبيق للهاتف",
"SMS, voice and e-mail alarms": "إنذارات عبر الرسائل النصية والمكالمات الصوتية والبريد الإلكتروني",
