"Remote maintenance": "الصيانة عن بُعد",
"Three levels of monitoring": "ثلاثة مستويات من المراقبة",
"0U built-in touch screen managing the UPS, AC, distribution and sensors inside one all-in-one cabinet.": "شاشة لمس مدمجة بارتفاع 0U تدير UPS والتكييف والتوزيع والحسّاسات داخل خزانة متكاملة واحدة.",
"Micro-module (SK-DEM)": "وحدة معيارية (SK-DEM)",
"SK-DEM + 21\" touch screen monitor the whole cold aisle: distribution, UPS, in-row AC, batteries, PDUs, environment, access and video.": "تراقب SK-DEM مع شاشة لمس 21\" الممر البارد بأكمله: التوزيع وUPS والتكييف بين الصفوف والبطاريات ووحدات PDU والبيئة والدخول والفيديو.",
"Room / multi-site DCIM": "DCIM للغرفة / مواقع متعددة",
"One SK-DEM per room collects data; hot-standby DCIM servers in the monitoring centre manage assets, operations, energy and capacity.": "تجمع وحدة SK-DEM واحدة لكل غرفة البيانات؛ وتدير خوادم DCIM الاحتياطية الساخنة في مركز المراقبة الأصول والتشغيل والطاقة والسعة.",
"Micro-module monitoring — features": "مراقبة الوحدات المعيارية — المزايا",
"All-round, integrated monitoring": "مراقبة شاملة ومتكاملة",
"Power distribution, environment, security, fire, video and access control are combined into one micro-module monitoring system covering everything.": "تُجمع مراقبة توزيع الطاقة والبيئة والأمن والحريق والفيديو والتحكم في الدخول في نظام مراقبة واحد للوحدة المعيارية يغطي كل شيء.",
"Highly integrated, neat": "تكامل عالٍ، ومظهر مرتّب",
"High-resolution touch screen with RS485, RS232, DI, DO and LAN ports. Data acquisition, processing, alarms and display in one; industrial-grade hardware and software, stable, good-looking and easy to install.": "شاشة لمس عالية الدقة مع منافذ RS485 وRS232 وDI وDO وLAN. جمع البيانات ومعالجتها والإنذارات والعرض في وحدة واحدة؛ عتاد وبرمجيات بمستوى صناعي، مستقرة وأنيقة وسهلة التركيب.",
"Complete management functions": "وظائف إدارة متكاملة",
"Real-time monitoring, energy-efficiency analysis and alarm filtering, plus data, user-rights and configuration management, logs, curves and reports — managed locally without a host PC.": "مراقبة لحظية، وتحليل كفاءة الطاقة وتصفية الإنذارات، إضافةً إلى إدارة البيانات وصلاحيات المستخدمين والتكوين، والسجلات والمنحنيات والتقارير — تُدار محليًا دون كمبيوتر مضيف.",
"Open standard interfaces": "واجهات قياسية مفتوحة",
"Standard third-party interfaces upload data over the network to a central platform, compatible with other vendors' systems for unified monitoring.": "ترفع الواجهات القياسية للأطراف الثالثة البيانات عبر الشبكة إلى منصة مركزية، متوافقة مع أنظمة الموردين الآخرين لمراقبة موحّدة.",
"All-in-one cabinet monitoring — features": "مراقبة الخزانة المتكاملة — المزايا",
"0U: built in, takes no rack space, neat": "0U: مدمجة، لا تشغل مساحة في الرف، ومرتّبة",
"True-colour capacitive screen, rich clear display": "شاشة سعوية بألوان حقيقية، وعرض غني وواضح",
"Responsive touch with swipe gestures": "لمس سريع الاستجابة مع إيماءات السحب",
"Swipe, pattern or PIN unlock": "فتح القفل بالسحب أو النمط أو الرمز",
"Dedicated integrated system, fast response": "نظام متكامل مخصص، واستجابة سريعة",
"One unit manages many smart devices plus door, smoke and water sensors": "وحدة واحدة تدير أجهزة ذكية كثيرة إضافةً إلى حسّاسات الأبواب والدخان والمياه",
"Front camera for snapshots and face recognition (optional)": "كاميرا أمامية للالتقاط والتعرف على الوجوه (اختيارية)",
"Built-in web interface, easy to manage": "واجهة ويب مدمجة، وسهولة في الإدارة",
"Northbound interface for networking many units": "واجهة شمالية لربط وحدات كثيرة بالشبكة",
"Rack U-position management without extra hardware": "إدارة مواضع U في الرف دون عتاد إضافي",
"Alarm-triggered actions": "إجراءات تُفعَّل بالإنذار",
"Micro-module monitoring V3.0": "مراقبة الوحدات المعيارية V3.0",
"The web platform shows the overall health of the cold aisle, equipment performance, faults and alarms in real time, greatly reducing day-to-day management work. Configuration is easy through the platform, so installation and commissioning need far less specialist IT staff.": "تعرض منصة الويب الحالة العامة للممر البارد، وأداء المعدات، والأعطال والإنذارات في الوقت الفعلي، ما يقلّل كثيرًا من أعمال الإدارة اليومية. ويسهل التكوين عبر المنصة، فيحتاج التركيب والتشغيل إلى عدد أقل بكثير من المتخصصين في تقنية المعلومات.",
