"Size 600 (W) × 1200 (D) × 2000 (H) mm; fully enclosed (cold aisle), tempered-glass front door, sheet-steel rear door": "المقاس 600 (عرض) × 1200 (عمق) × 2000 (ارتفاع) مم؛ مغلقة بالكامل (ممر بارد)، باب أمامي من الزجاج المقسّى، باب خلفي من الصاج الفولاذي",
