"Accessories": "الملحقات",
"pair": "زوج",
"Shelves and L-rails for 19\" cabinets": "رفوف وقضبان L لخزائن 19\"",
"Power supply & distribution": "التغذية وتوزيع الطاقة",
"3–10 kVA rack-mount high-frequency online UPS": "UPS أونلاين عالي التردد للرف 3–10 kVA",
"UPS monitoring card": "بطاقة مراقبة UPS",
"RS485 / RS232 interface, for 3–10 kVA UPS": "واجهة RS485 / RS232، لـ UPS بقدرة 3–10 kVA",
