"Rack-mount distribution unit": "وحدة توزيع للرف",
"UPS input/output distribution, 3U; maintenance bypass and extra output ports": "توزيع دخل/خرج UPS، 3U؛ مسار جانبي للصيانة ومنافذ خرج إضافية",
"Rack PDU": "PDU للرف",
"2 per cabinet, side-mounted left and right, with industrial connector; outlets GB 10 A / 16 A, C13 or C19 as required": "2 لكل خزانة، مركّبة جانبيًا يمينًا ويسارًا، مع موصل صناعي؛ مقابس GB 10 أمبير / 16 أمبير أو C13 أو C19 حسب الحاجة",
"Power cables": "كابلات الطاقة",
