"Specifications are for reference only; the final confirmed specification applies to delivery.": "المواصفات للمرجعية فقط؛ والمواصفات النهائية المؤكدة هي التي تُطبَّق على التسليم.",
"Custom Mini UPS — OEM & ODM": "Mini UPS حسب الطلب — OEM وODM",
"Your outputs, battery and brand. OEM from 1000 pcs; ODM sample fee US$2,000, refunded in your mass-production order.": "مخارجك وبطاريتك وعلامتك التجارية. OEM ابتداءً من 1000 قطعة؛ رسوم عيّنة ODM 2,000 دولار أمريكي، تُسترد في طلب الإنتاج الكمي.",
"Design yours": "صمّم طرازك",
