"For factories and other industrial applications, please choose a low-frequency (transformer-based) UPS.": "للمصانع والتطبيقات الصناعية الأخرى، يُرجى اختيار UPS منخفض التردد (قائم على محوّل).",
"Load entered in kW is treated as kVA (output power factor 1). For loads with a low power factor, enter the kVA value.": "يُعامَل الحمل المُدخل بالكيلوواط على أنه kVA (معامل قدرة الخرج 1). للأحمال ذات معامل القدرة المنخفض، أدخل قيمة kVA.",
"Engineering configurator": "المُكوِّن الهندسي",
"Size a modular UPS system": "حدّد حجم نظام UPS معياري",
"Enter the site and load data. The configurator derates for altitude, sizes modules with redundancy, defines the battery to the constant-power method, and checks charging, inrush, currents and installation. Every assumption is listed below the result.": "أدخل بيانات الموقع والحمل. يخفّض المُكوِّن القدرة حسب الارتفاع، ويحدّد حجم الوحدات مع التكرار، ويحدّد البطارية بطريقة القدرة الثابتة، ويتحقق من الشحن وتيار الاندفاع والتيارات والتركيب. وتُدرج كل الافتراضات أسفل النتيجة.",
"Site and grid": "الموقع والشبكة",
