"440 / 480 V 3-phase": "440 / 480 فولت ثلاثي الطور",
"Modular UPS (10 kVA and above) run on three-phase power. Many sites in the Americas use 480 V at 60 Hz.": "تعمل أجهزة UPS المعيارية (10 kVA فما فوق) بتغذية ثلاثية الطور. وتستخدم مواقع كثيرة في الأمريكتين 480 فولت بتردد 60 هرتز.",
