"Largest start-up step (inrush)": "أكبر خطوة بدء تشغيل (تيار الاندفاع)",
"Extra kW for a few seconds when the largest motor or device starts.": "كيلوواط إضافية لبضع ثوانٍ عند بدء تشغيل أكبر محرك أو جهاز.",
