"Sized by discharge current (max. 3C), so this bank gives about {r} min at this load.": "محدَّد حسب تيار التفريغ (بحد أقصى 3C)، لذا يعطي هذا البنك نحو {r} دقيقة عند هذا الحمل.",
"High-voltage LFP with BMS, voltage window 448–584 V, inside the UPS range 360–600 V DC.": "LFP عالي الجهد مع BMS، نافذة الجهد 448–584 فولت، ضمن نطاق UPS 360–600 فولت مستمر.",
"Includes aging (×1.25), design margin (×1.10) and 95% battery-mode efficiency. For reference only — final selection is confirmed by our engineers.": "يشمل التقادم (×1.25) وهامش التصميم (×1.10) وكفاءة وضع البطارية 95%. للمرجعية فقط — يؤكد مهندسونا الاختيار النهائي.",
